package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.POST("/users", func(c *gin.Context) {
		c.JSON(http.StatusCreated, gin.H{"id": 1}) // 201 Created
	})
	r.GET("/users/1", func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": "用户不存在"}) // 404 Not Found
	})

	// 常用状态码：
	// 200 OK 成功
	// 201 Created 创建成功
	// 204 No Content 成功但没有响应体
	// 400 Bad Request 参数格式不对
	// 401 Unauthorized 没登录或令牌无效
	// 403 Forbidden 登录了但没权限
	// 404 Not Found 资源不存在
	// 409 Conflict 与当前状态冲突，比如重复提交
	// 422 Unprocessable Entity 格式对但语义不合法
	// 500 Internal Server Error 服务端自己出错

	req := httptest.NewRequest(http.MethodPost, "/users", nil)
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println(w.Code, w.Body.String())
}

