		// 在写响应体之前设置响应头
		c.Header("Content-Disposition", `attachment; filename="a.txt"`)
		c.Header("X-Request-Id", "req-001")
		c.Data(http.StatusOK, "text/plain; charset=utf-8", []byte("文件内容"))
	})

	req := httptest.NewRequest(http.MethodGet, "/download", nil)
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println(w.Header().Get("X-Request-Id"))
	fmt.Println(w.Header().Get("Content-Disposition"))
}

