package main

import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.GET("/stream", func(c *gin.Context) {
		n := 0
		c.Stream(func(w io.Writer) bool {
			n++
			fmt.Fprintf(w, "第 %d 段\n", n)
			return n < 3 // 返回 false 表示流结束了
		})
	})

	// 流式响应要真的有连接，用 httptest 起一个服务器
	srv := httptest.NewServer(r)
	defer srv.Close()

	resp, err := http.Get(srv.URL + "/stream")
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(resp.Body)
	fmt.Print(string(body))
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

type User struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
}

// 统一响应体
type Response struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
	Data    any    `json:"data,omitempty"`
}

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()

	// 成功：统一响应格式 + 状态码 + 自定义响应头
	r.GET("/users/1", func(c *gin.Context) {
		c.Header("X-Request-Id", "req-001")
		c.JSON(http.StatusOK, Response{
			Code:    0,
			Message: "ok",
			Data:    User{ID: 1, Name: "张三"},
		})
	})

	// 创建成功：201
	r.POST("/users", func(c *gin.Context) {
		c.JSON(http.StatusCreated, Response{
			Code:    0,
			Message: "ok",
			Data:    User{ID: 2, Name: "李四"},
		})
	})

	// 未认证：中止处理链并回 JSON
	r.GET("/admin", func(c *gin.Context) {
		if c.GetHeader("X-Token") == "" {
			c.AbortWithStatusJSON(http.StatusUnauthorized, Response{
				Code:    401,
				Message: "未登录",
			})
			return
		}
		c.String(http.StatusOK, "管理员面板")
	})

	// 删除成功：204 没有响应体
	r.DELETE("/users/1", func(c *gin.Context) {
		c.Status(http.StatusNoContent)
	})

	for _, path := range []string{"/users/1", "/admin", "/users/1"} {
		req := httptest.NewRequest(http.MethodGet, path, nil)
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		fmt.Println(w.Code, w.Body.String())
	}
}
